<script setup>defineProps({sync:Boolean});defineEmits(['reset','top','toggle'])</script><template><div class="controls"><span>View Control (3D)</span><button @click="$emit('reset')">↻　Reset View</button><button @click="$emit('top')">▦　Top View</button><label><input type="checkbox" :checked="sync" @change="$emit('toggle',$event.target.checked)"> Sync 3D View</label><p>{{sync?'3D views are synchronized.':'3D views are independent.'}}<br>{{sync?'Rotating one wafer will rotate the other.':'Each wafer can be rotated separately.'}}</p></div></template><style scoped>.controls{display:flex;justify-content:flex-end;align-items:center;gap:12px;padding-top:10px;font-size:9px}.controls>span{margin-right:auto;font-weight:700}.controls button{height:31px;padding:0 18px;background:#fff;border:1px solid #d7e0ea;border-radius:4px;font-size:9px}.controls label{display:flex;align-items:center;gap:5px}.controls p{margin:0;padding:8px 16px;color:#075ce2;background:#edf5ff;border:1px solid #c5ddff;border-radius:4px;line-height:1.5}</style>

